	end,
	IsRelative = function(arg1)
		return arg1.Increment ~= nil
	end,
	GetTarget = function(arg1, arg2)
		if arg1.Increment then
			return (arg2 or 0) + arg1.Increment
		end

		if arg1.Upgrade then
			return 1
		end

		return arg1.Target or 1
	end,
	GetMinCash = function(arg1)
		if arg1.MinCash then
			return arg1.MinCash
		end

		if not arg1.Upgrade then
			return 0
		end

		local var2 = var3[arg1.Upgrade]
		if not var2 then
			return 0
		end

		for k1, v1 in tbl3, nil do
			if v1.Price > var2.Price then
				continue
			end

			return v1.MinCash
		end

		return 0
	end,
}

tbl5.GetDisplayText = function(arg1)
	if arg1.Text then
		return arg1.Text
	end

	if arg1.Format then
		local var4 = arg1.Increment
		local var5 = arg1.Format
		var4 = var4 or tbl5.GetTarget(arg1)
		return string.format(var5, var4)
	end

	local var7 = var3[arg1.Upgrade]
	if arg1.Upgrade and var7 then
		return (("Buy the %* upgrade!"):format(var7.DisplayName))
	end

	return "Complete your objective!"
end

return tbl5

