local tbl4 = { 0, 1, 2, 3, 4, 5, 6, 7 }
local function getCorners(arg1, arg2, arg3)
	local tbl1 = {}
	for k1, v1 in pairs(arg3) do
		tbl1[k1] = arg1 * (arg2 * Vector3.new(math.floor(v1 / 4) % 2 * 2 - 1, math.floor(v1 / 2) % 2 * 2 - 1, 2 * (v1 % 2) - 1))
