tbl1.Calibrate = function(arg1)
	local var1 = arg1.ViewportFrame.AbsoluteSize
	local tbl1 = { aspect = var1.X / var1.Y, yFov2 = math.rad(arg1.Camera.FieldOfView / 2) }
	tbl1.tanyFov2 = math.tan(tbl1.yFov2)
	tbl1.xFov2 = math.atan(tbl1.tanyFov2 * tbl1.aspect)
	tbl1.tanxFov2 = math.tan(tbl1.xFov2)
	tbl1.cFov2 = math.atan(tbl1.tanyFov2 * math.min(1, tbl1.aspect))
	tbl1.sincFov2 = math.sin(tbl1.cFov2)
