end

local function viewProjectionEdgeHits(arg1, arg2, arg3, arg4)
	local num1 = -math.huge
	local num2 = math.huge
	for k1, v1 in pairs(arg1) do
		local var1 = arg4 * (arg3 - v1.Z)
		local var2 = v1[arg2] + var1
		local var3 = v1[arg2] - var1
		num1 = math.max(num1, var2, var3)
		num2 = math.min(num2, var2, var3)
	end

	return num1, num2
end

tbl1.GetMinimumFitCFrame = function(arg1, arg2)
	if not arg1.Model then
