		tbl1[i1] = var4
		var3 = math.min(var3, var4.Z)
	end

	local var5, var6 = viewProjectionEdgeHits(tbl1, "X", var3, arg1._viewport.tanxFov2)
	local var7, var8 = viewProjectionEdgeHits(tbl1, "Y", var3, arg1._viewport.tanyFov2)
	return arg2 * CFrame.new((var5 + var6) / 2, (var7 + var8) / 2, var3 + math.max((var5 - var6) / 2 / arg1._viewport.tanxFov2, (var7 - var8) / 2 / arg1._viewport.tanyFov2))
end

